namespace Aster {
 public partial class Desktop {
  bool scanView,routeSync;
  readonly Dictionary<string,List<Entry>> scanCache=new Dictionary<string,List<Entry>>();
  List<SortRoute> watchRoutes;
  List<string> watchGameRoots,watchGameFiles;
  bool watchKeepSources;
  void SetupRevision(){
   if(state.Settings.Version<4){if(!state.HasLibraryData)foreach(var item in state.Settings.Shortcuts.Where(s=>s.Group=="Game"||s.Group=="Game / launcher"))LibraryState.Add(state.Settings,"Game",new[]{item.Path});state.Settings.Version=4;state.Save();}
   ((Panel)Find<Button>("NavApps").Parent).Children.Remove(Find<Button>("NavApps"));Find<Grid>("PageHost").Children.Remove(Find<Grid>("AppsPage"));
   Click("LibrarySaved",()=>{scanView=false;ApplyLibraryFilter();});Click("LibraryScanned",()=>{scanView=true;ApplyLibraryFilter();});
   Click("LibraryAddFile",()=>{var dialog=new OpenFileDialog {Multiselect=true,Title="Thêm vào thư viện "+libraryType,Filter=libraryType=="Game"?"File mở game|*.exe;*.lnk;*.url":libraryType=="Office"?"Office|*.doc;*.docx;*.docm;*.xls;*.xlsx;*.xlsm;*.ppt;*.pptx;*.pptm;*.pdf;*.rtf;*.odt;*.ods;*.odp;*.csv":"Ảnh|*.png;*.jpg;*.jpeg;*.gif;*.bmp;*.webp;*.heic;*.tif;*.tiff"};if(dialog.ShowDialog(w)==true)SaveLibraryFiles(dialog.FileNames);});
   Click("LibrarySaveSelection",()=>SaveLibraryFiles(Find<DataGrid>("LibraryList").SelectedItems.Cast<Entry>().Select(x=>x.Path).ToList()));
   Click("LibraryRemove",()=>{LibraryState.Remove(state.Settings,libraryType,Find<DataGrid>("LibraryList").SelectedItems.Cast<Entry>().Select(x=>x.Path).ToList());state.Save();ApplyLibraryFilter();RefreshLibraryCounts();});
   Click("LibraryRename",()=>EditLibrary(false));Click("LibraryCollection",()=>EditLibrary(true));Click("LibraryFavorite",()=>{var paths=Find<DataGrid>("LibraryList").SelectedItems.Cast<Entry>().Select(x=>x.Path).ToList();foreach(var item in state.Settings.LibraryItems.Where(x=>x.Category==libraryType&&paths.Contains(x.Path,StringComparer.OrdinalIgnoreCase)))item.Favorite=!item.Favorite;state.Save();ApplyLibraryFilter();RefreshLibraryCounts();});
   Find<TextBox>("LibrarySearch").TextChanged+=(s,e)=>ApplyLibraryFilter();Find<CheckBox>("LibraryOnlyFavorites").Checked+=(s,e)=>ApplyLibraryFilter();Find<CheckBox>("LibraryOnlyFavorites").Unchecked+=(s,e)=>ApplyLibraryFilter();
   Find<DataGrid>("LibraryList").DragOver+=(s,e)=>{e.Effects=e.Data.GetDataPresent(DataFormats.FileDrop)?DragDropEffects.Link:DragDropEffects.None;e.Handled=true;};Find<DataGrid>("LibraryList").Drop+=(s,e)=>{if(e.Data.GetDataPresent(DataFormats.FileDrop)){SaveLibraryFiles((string[])e.Data.GetData(DataFormats.FileDrop));e.Handled=true;}};
   Click("CloseDetail",()=>Details(null));SetInspector(null);RefreshLibraryCounts();SetupRouteEditor();SetupCategoryIcons();UpgradeVault();
  }
  void SaveLibraryFiles(IEnumerable<string> paths){int count=LibraryState.Add(state.Settings,libraryType,paths);if(libraryType=="Game")InvalidatePlan();state.Save();scanView=false;ApplyLibraryFilter();RefreshLibraryCounts();SetStatus("Đã thêm "+count+" mục vào "+libraryType+". Liên kết được lưu, file gốc được giữ nguyên.");}
  void EditLibrary(bool collection){var entry=Find<DataGrid>("LibraryList").SelectedItem as Entry;if(entry==null)return;var item=state.Settings.LibraryItems.FirstOrDefault(x=>x.Category==libraryType&&x.Path.Equals(entry.Path,StringComparison.OrdinalIgnoreCase));if(item==null)return;string value=Prompt(collection?"Bộ sưu tập":"Tên hiển thị",collection?"Đặt nhóm riêng, ví dụ Công việc / Cá nhân / Indie":"Chỉ đổi tên trong thư viện, không đổi tên file gốc.",collection?item.Collection:item.Title);if(String.IsNullOrWhiteSpace(value))return;if(collection)item.Collection=value.Trim();else item.Title=value.Trim();state.Save();ApplyLibraryFilter();RefreshLibraryCounts();}
  void SetInspector(Entry entry){var root=(Grid)w.Content;root.ColumnDefinitions[2].Width=new GridLength(entry==null?64:350);Find<StackPanel>("DetailEmpty").Visibility=entry==null?Visibility.Visible:Visibility.Collapsed;Find<ScrollViewer>("DetailBody").Visibility=entry==null?Visibility.Collapsed:Visibility.Visible;Find<Border>("DetailTip").Visibility=Visibility.Collapsed;}
  FrameworkElement IconLabel(string label){var stack=new StackPanel {Orientation=Orientation.Horizontal,VerticalAlignment=VerticalAlignment.Center};string path=label=="Word"?"file.docx":label=="Excel"?"file.xlsx":label=="PowerPoint"?"file.pptx":label=="PDF"?"file.pdf":label=="Ảnh"?"file.png":label=="File nén"?"file.zip":label=="Bộ cài"?"file.exe":null;
   if(path!=null)stack.Children.Add(new Image {Source=ShellIcons.Get(path,false),Width=20,Height=20,Margin=new Thickness(0,0,8,0)});
   else if(label=="Office"){var badge=new Border {Background=new SolidColorBrush(Color.FromRgb(221,91,49)),CornerRadius=new CornerRadius(4),Width=20,Height=20,Margin=new Thickness(0,0,8,0)};badge.Child=new TextBlock {Text="O",FontFamily=new FontFamily("Segoe UI"),FontWeight=FontWeights.Bold,Foreground=Brushes.White,HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center};stack.Children.Add(badge);}
   else stack.Children.Add(new TextBlock {Text=label.Contains("Game")?"\uE7FC":label.Contains("Video")||label.Contains("Âm thanh")?"\uE714":"\uE8A9",FontFamily=new FontFamily("Segoe MDL2 Assets"),FontSize=17,Foreground=(Brush)w.Resources["Blue"],Margin=new Thickness(0,2,8,0)});
   var text=Text(label,12);text.TextWrapping=TextWrapping.NoWrap;stack.Children.Add(text);return stack;
  }
  string ChoiceText(ComboBox box){var item=box.SelectedItem as ComboBoxItem;return item==null?(box.SelectedItem==null?"":box.SelectedItem.ToString()):(item.Tag as string??item.Content.ToString());}
  void DecorateChoices(ComboBox box){foreach(var obj in box.Items){var item=obj as ComboBoxItem;if(item==null)continue;string label=item.Content.ToString();item.Tag=label;item.Content=IconLabel(label);}}
  void SetupCategoryIcons(){DecorateChoices(Find<ComboBox>("TypeFilter"));DecorateChoices(Find<ComboBox>("VaultGroup"));foreach(var pair in new[]{Tuple.Create("OfficeAll","Office"),Tuple.Create("OfficeWord","Word"),Tuple.Create("OfficeExcel","Excel"),Tuple.Create("OfficeSlides","PowerPoint"),Tuple.Create("OfficePdf","PDF")})Find<Button>(pair.Item1).Content=IconLabel(pair.Item2);}
  void RefreshLibraryCounts(){var home=(StackPanel)Find<ScrollViewer>("HomePage").Content;var cards=home.Children.OfType<System.Windows.Controls.Primitives.UniformGrid>().FirstOrDefault(p=>p.Columns==3);if(cards==null)return;string[] categories={"Ảnh","Office","Game"};for(int i=0;i<cards.Children.Count&&i<3;i++){var button=cards.Children[i] as Button;var content=button==null?null:button.Content as StackPanel;if(content==null)continue;var caption=content.Children.OfType<TextBlock>().LastOrDefault();if(caption!=null)caption.Text=state.Settings.LibraryItems.Count(x=>x.Category==categories[i])+" mục đã lưu";}}
  void SetupRouteEditor(){var host=Find<StackPanel>("RoutesPanel");host.Children.Clear();int i=0;foreach(var route in state.Settings.SortRoutes){int n=i++;var row=new Grid {Margin=new Thickness(0,0,0,10)};row.ColumnDefinitions.Add(new ColumnDefinition {Width=new GridLength(200)});row.ColumnDefinitions.Add(new ColumnDefinition());row.ColumnDefinitions.Add(new ColumnDefinition {Width=GridLength.Auto});var toggle=new CheckBox {Content=IconLabel(route.Category),IsChecked=route.Enabled,VerticalAlignment=VerticalAlignment.Center};w.RegisterName("RouteEnabled"+n,toggle);row.Children.Add(toggle);var path=new TextBox {Text=route.Destination,Margin=new Thickness(0,0,10,0),ToolTip="Nơi lưu "+route.Category};w.RegisterName("RoutePath"+n,path);Grid.SetColumn(path,1);row.Children.Add(path);var browse=new Button {Content="Chọn / tạo",Margin=new Thickness(0)};Grid.SetColumn(browse,2);row.Children.Add(browse);browse.Click+=(s,e)=>{string selectedPath=PickFolder();if(selectedPath!=null)path.Text=selectedPath;};path.TextChanged+=(s,e)=>{route.Destination=path.Text;if(!routeSync){state.Save();InvalidatePlan();}};toggle.Checked+=(s,e)=>{route.Enabled=true;state.Save();InvalidatePlan();};toggle.Unchecked+=(s,e)=>{route.Enabled=false;state.Save();InvalidatePlan();};host.Children.Add(new Border {Child=row,Padding=new Thickness(14,12,14,2),CornerRadius=new CornerRadius(9),Background=(Brush)w.Resources["Surface"],Margin=new Thickness(0,0,0,8)});}
   Find<CheckBox>("KeepSourcesChoice").IsChecked=state.Settings.KeepSourceFolders;Find<CheckBox>("KeepSourcesChoice").Checked+=(s,e)=>{state.Settings.KeepSourceFolders=true;state.Save();InvalidatePlan();};Find<CheckBox>("KeepSourcesChoice").Unchecked+=(s,e)=>{state.Settings.KeepSourceFolders=false;state.Save();InvalidatePlan();};
   Find<TextBox>("DestPath").TextChanged+=(s,e)=>SetDefaultRoutes();if(!String.IsNullOrEmpty(state.Settings.Destination)&&state.Settings.SortRoutes.All(r=>String.IsNullOrEmpty(r.Destination)))SetDefaultRoutes();
  }
  void SetDefaultRoutes(){string root=Find<TextBox>("DestPath").Text;if(String.IsNullOrWhiteSpace(root))return;try{root=Path.GetFullPath(root);routeSync=true;for(int i=0;i<state.Settings.SortRoutes.Count;i++){var route=state.Settings.SortRoutes[i];route.Destination=Path.Combine(root,route.Category);Find<TextBox>("RoutePath"+i).Text=route.Destination;}state.Settings.Destination=root;state.Save();InvalidatePlan();}catch(Exception e){SetStatus(e.Message);}finally{routeSync=false;}}
  List<SortRoute> SnapshotRoutes(){return state.Settings.SortRoutes.Select(r=>new SortRoute {Category=r.Category,Destination=r.Destination,Enabled=r.Enabled}).ToList();}
  List<string> SortingRoots(){var roots=state.Settings.GameRoots.ToList();foreach(var item in state.Settings.LibraryItems.Where(x=>x.Category=="Game")){string root=Path.GetDirectoryName(item.Path);if(!new[]{"Downloads","Desktop"}.Contains(Path.GetFileName(root),StringComparer.OrdinalIgnoreCase))roots.Add(root);}return roots.Distinct(StringComparer.OrdinalIgnoreCase).ToList();}
  List<string> SortingFiles(){return state.Settings.LibraryItems.Where(x=>x.Category=="Game").Select(x=>x.Path).ToList();}
  string SortLabel(string source,List<SortRoute> routes){var target=routes.FirstOrDefault(r=>r.Enabled&&!String.IsNullOrWhiteSpace(r.Destination));return target==null?Path.GetFileName(source.TrimEnd('\\')):SourceLabel(source,target.Destination);}
  void RefreshMovedLinks(){bool changed=false;foreach(var record in state.History()){string from=record.Undone?record.To:record.From,to=record.Undone?record.From:record.To;foreach(var item in state.Settings.LibraryItems){if(!File.Exists(item.Path)&&Fs.Within(item.Path,from)){string suffix=item.Path.Substring(from.TrimEnd('\\').Length).TrimStart('\\');string target=suffix.Length==0?to:Path.Combine(to,suffix);if(File.Exists(target)){item.Path=target;changed=true;}}}foreach(var item in state.Settings.Shortcuts){if(!File.Exists(item.Path)&&item.Path.Equals(from,StringComparison.OrdinalIgnoreCase)&&File.Exists(to)){item.Path=to;changed=true;}}}if(changed){state.Save();if(page=="Library")ApplyLibraryFilter();}}
  async void PreviewSorting(){string source=Find<TextBox>("SourcePath").Text;var routes=SnapshotRoutes();string label=SortLabel(source,routes);int revision=ruleRevision;var gameRoots=SortingRoots();var gameFiles=SortingFiles();bool keep=state.Settings.KeepSourceFolders;Find<TextBlock>("RuleStatus").Text="Đang kiểm tra file nằm trực tiếp trong nguồn…";try{var result=await Task.Run(()=>FolderSorting.Plan(source,routes,label,gameRoots,gameFiles,keep,CancellationToken.None));if(revision!=ruleRevision)return;plan=result;Find<DataGrid>("PlanList").ItemsSource=plan;Find<Button>("ApplyRules").IsEnabled=plan.Count>0;Find<TextBlock>("RuleStatus").Text=plan.Count+" file sẽ được chuyển tới nơi lưu tương ứng. Tất cả thư mục con được giữ nguyên.";state.Save();}catch(Exception e){Error(e.Message);}}
  void ToggleSorting(){if(watching){StopWatch();return;}string source=Find<TextBox>("SourcePath").Text;var routes=SnapshotRoutes();string label=SortLabel(source,routes);var roots=SortingRoots();var files=SortingFiles();FolderSorting.Plan(source,routes,label,roots,files,state.Settings.KeepSourceFolders,CancellationToken.None);watchSource=source;watchLabel=label;watchRoutes=routes;watchGameRoots=roots;watchGameFiles=files;watchKeepSources=state.Settings.KeepSourceFolders;watchDest=Find<TextBox>("DestPath").Text;stable.Clear();watching=true;watchTimer.Start();Find<Button>("WatchRules").Content="Tắt theo dõi";Find<TextBlock>("RuleStatus").Text="Đang theo dõi file trực tiếp trong "+source+". File mới, ổn định sẽ được chuyển mỗi 8 giây.";state.Save();}
  void UpgradeVault(){var toolbar=(WrapPanel)Find<Button>("VaultAdd").Parent;foreach(var item in new[]{Tuple.Create("VaultRename","Tên hiển thị"),Tuple.Create("VaultMoveGroup","Đổi nhóm"),Tuple.Create("VaultLocation","Mở vị trí")}){var button=new Button {Content=item.Item2};w.RegisterName(item.Item1,button);toolbar.Children.Add(button);}var search=new TextBox {Width=240,Margin=new Thickness(0,10,8,0),ToolTip="Tìm ứng dụng trong kho"};w.RegisterName("VaultSearch",search);toolbar.Children.Add(search);search.TextChanged+=(s,e)=>RefreshVault();
   Click("VaultRename",()=>{var entry=Find<ListBox>("VaultItems").SelectedItem as Entry;if(entry==null)return;var shortcut=state.Settings.Shortcuts.FirstOrDefault(x=>x.Path.Equals(entry.Path,StringComparison.OrdinalIgnoreCase));if(shortcut==null)return;string name=Prompt("Tên hiển thị","Không đổi tên file EXE gốc.",shortcut.Name);if(!String.IsNullOrWhiteSpace(name)){shortcut.Name=name.Trim();state.Save();RefreshVault();}});Click("VaultMoveGroup",()=>{var paths=Find<ListBox>("VaultItems").SelectedItems.Cast<Entry>().Select(x=>x.Path).ToList();foreach(var item in state.Settings.Shortcuts.Where(x=>paths.Contains(x.Path,StringComparer.OrdinalIgnoreCase)))item.Group=item.Group=="Game"?"Ứng dụng":"Game";state.Save();RefreshVault();});Click("VaultLocation",()=>{var entry=Find<ListBox>("VaultItems").SelectedItem as Entry;if(entry!=null)OpenFolder(Path.GetDirectoryName(entry.Path));});
   var navButton=Find<Button>("NavVault");navButton.Content=IconLabel("Kho ứng dụng");
  }
 }
}


